INSERT INTO `addons` VALUES ('6a8168cf-134e-49c6-951c-1ae9f6969781','TallyPrime XML Data Bridge','tally-importer','Bi-directional ledger & voucher sync with Tally ERP 9 / Prime','Import vouchers, customer accounts, and trial balances seamlessly from desktop Tally installations into cloud ledgers.',NULL,'Accounting','active',59.00,'Layers',NULL,'[\"XML Schema Mapping\",\"Voucher Validation\",\"Zero Duplicate Safeguard\"]',NULL,NULL,NULL,NULL,NULL,0,'2026-09-29 12:41:28.316','2026-09-29 12:41:28.316'),('6d74e678-8648-4a77-82b2-a2150635f176','Point of Sale (POS) Retail Suite','pos','Fast barcode checkout, cash registers & receipt printers','High-speed retail counter interface with thermal receipt printing, cash register shifts, barcode scanning, and multi-warehouse stock decrementing.',NULL,'Commerce','active',69.00,'Store',NULL,'[\"Barcode Scanning\",\"Thermal Printing\",\"Cash Register Audits\"]',NULL,NULL,NULL,NULL,NULL,1,'2026-09-29 12:41:28.315','2026-09-29 12:41:28.315'),('af521780-e377-45e5-92de-f55e9447c577','WhatsApp Business Automations','whatsapp-alerts','Automated payslip, attendance & shift WhatsApp notifications','Direct WhatsApp Cloud API gateway sending interactive notification templates, approval buttons, and clock-in reminders to workforce numbers.',NULL,'Communication','active',49.00,'MessageSquare',NULL,'[\"Instant Payslip Dispatch\",\"Shift Broadcasts\",\"Late Clock-in Alerts\"]',NULL,NULL,NULL,NULL,NULL,1,'2026-09-29 12:41:28.309','2026-09-29 12:41:28.309'),('b5acb4f4-4db5-43aa-9da6-6ff154332069','Multi-Currency Financials','multi-currency','Real-time FX rates and foreign currency general ledger accounts','Transact globally in 140+ currencies with automatic daily forex revaluation and realized/unrealized gain-loss calculations.',NULL,'Finance','active',89.00,'Landmark',NULL,'[\"140+ Currencies\",\"Auto FX Sync\",\"Unrealized Gain Ledgers\"]',NULL,NULL,NULL,NULL,NULL,0,'2026-09-29 12:41:28.318','2026-09-29 12:41:28.318'),('bf0a7cdb-7677-4265-8a99-3fde9a862f52','Biometric Device Cloud Sync','biometric-sync','Real-time push gateway for ZKTeco, eSSL, Realtime & Hikvision','Plug-and-play ADMS push protocol gateway streaming hardware punch logs directly to payroll ledgers in sub-100ms latency.',NULL,'Hardware','active',79.00,'Fingerprint',NULL,'[\"Live ADMS Push Listener\",\"Auto-punch Reconciliation\",\"Geofence Verification\"]',NULL,NULL,NULL,NULL,NULL,1,'2026-09-29 12:41:28.311','2026-09-29 12:41:28.311'),('c60d20fd-e771-444d-a2af-e342a160d4dc','Neural AI OCR Invoice Reader','ai-ocr','Extract paper bills and supplier invoices into MySQL ledgers','Computer vision and LLM parsing extracting vendor GST, line items, and taxes with automatic general ledger double-entry posting.',NULL,'AI & Automation','active',99.00,'Sparkles',NULL,'[\"Document Drag-and-Drop\",\"Automatic PO Creation\",\"Ledger Auto-Posting\"]',NULL,NULL,NULL,NULL,NULL,1,'2026-09-29 12:41:28.313','2026-09-29 12:41:28.313');
