INSERT INTO `form_fields` VALUES ('25818182-86f4-4e75-9f8d-256e1c5accaa','d52930b4-afdc-4ef7-a2d7-99f7e4e1b739','How helpful was your assigned onboarding buddy/mentor?',NULL,'rating_scale','[\"1\",\"2\",\"3\",\"4\",\"5\"]',1,2,NULL,NULL,'2026-09-12 09:31:17.138','2026-09-12 09:31:17.138'),('3f153db1-9664-44e2-8335-6a7ecaa349c8','b43870cf-6954-4bc0-a6e7-a766fdc980e5','Do you have the necessary tools & hardware to succeed in your role?',NULL,'radio','[\"Yes, completely\",\"Mostly adequate\",\"Needs improvement\",\"No, lacking essentials\"]',1,1,NULL,NULL,'2026-09-12 09:31:17.131','2026-09-12 09:31:17.131'),('42c24f33-fb18-4268-a0d3-ba4c9f6c097d','d52930b4-afdc-4ef7-a2d7-99f7e4e1b739','Overall Onboarding Experience',NULL,'rating_scale','[\"1\",\"2\",\"3\",\"4\",\"5\"]',1,0,NULL,NULL,'2026-09-12 09:31:17.138','2026-09-12 09:31:17.138'),('4a590774-2d96-4b7b-b954-ebb108efd1fe','d52930b4-afdc-4ef7-a2d7-99f7e4e1b739','Any suggestions to improve onboarding for future team members?',NULL,'long_text',NULL,0,3,'Tell us your thoughts...',NULL,'2026-09-12 09:31:17.138','2026-09-12 09:31:17.138'),('4f0e0d19-b842-41d9-b130-6ffa4ae68382','b43870cf-6954-4bc0-a6e7-a766fdc980e5','Overall Job Satisfaction & Happiness','Rate from 1 (Very Dissatisfied) to 5 (Extremely Satisfied)','rating_scale','[\"1\",\"2\",\"3\",\"4\",\"5\"]',1,0,NULL,NULL,'2026-09-12 09:31:17.131','2026-09-12 09:31:17.131'),('5050d2e5-561a-4285-b6bf-814ac51b8148','ed057038-9bbc-4cde-91c1-c9343c063c54','Urgency Level',NULL,'radio','[\"Standard (5-7 days)\",\"High (2-3 days)\",\"Critical / Blocker (Immediate)\"]',1,3,NULL,NULL,'2026-09-12 09:31:17.134','2026-09-12 09:31:17.134'),('65e734b1-06a7-4554-9a36-83f5804f40e4','b43870cf-6954-4bc0-a6e7-a766fdc980e5','What is one thing the management can do to make your work better?','Open-ended anonymous feedback or ideas for improvement','long_text',NULL,0,3,'Share your constructive ideas...',NULL,'2026-09-12 09:31:17.131','2026-09-12 09:31:17.131'),('7199944b-05e2-4b35-83db-de368d6698c7','ed057038-9bbc-4cde-91c1-c9343c063c54','Requested Equipment / License Type',NULL,'select','[\"Second 4K Monitor\",\"MacBook Pro M3 Upgrade\",\"Ergonomic Mechanical Keyboard\",\"Noise-Cancelling Headset\",\"AWS / Cloud Dedicated Credits\",\"JetBrains / Figma Enterprise License\"]',1,0,NULL,NULL,'2026-09-12 09:31:17.134','2026-09-12 09:31:17.134'),('c211e1be-3700-4a27-8978-76c0c224f085','ed057038-9bbc-4cde-91c1-c9343c063c54','Business Justification & Project Need','Explain why this equipment is needed for your deliverables','long_text',NULL,1,1,'e.g. Needed for mobile app responsive testing and Figma prototype design...',NULL,'2026-09-12 09:31:17.134','2026-09-12 09:31:17.134'),('c73950a8-b621-41b2-a73b-e2d4abe7e538','ed057038-9bbc-4cde-91c1-c9343c063c54','Required Delivery / Urgency Date',NULL,'date',NULL,1,2,NULL,NULL,'2026-09-12 09:31:17.134','2026-09-12 09:31:17.134'),('d15570e0-9866-4bf2-8553-94ad356fe41e','d52930b4-afdc-4ef7-a2d7-99f7e4e1b739','Was your work equipment & system access ready on Day 1?',NULL,'radio','[\"Yes, everything was set up\",\"Minor delays on accounts\",\"Major delays on hardware\"]',1,1,NULL,NULL,'2026-09-12 09:31:17.138','2026-09-12 09:31:17.138'),('fc196d3e-0b72-44ed-9072-ddda6387341a','b43870cf-6954-4bc0-a6e7-a766fdc980e5','How satisfied are you with work-life balance & flexibility?',NULL,'rating_scale','[\"1\",\"2\",\"3\",\"4\",\"5\"]',1,2,NULL,NULL,'2026-09-12 09:31:17.131','2026-09-12 09:31:17.131');
